#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    long num = strtol(argv[1], NULL, 10);
    if (num < 0 || num > 1000000000) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    if (num == 0 || num == 1) {
        printf("%ld^1\n", num);
        return 0;
    }
    printf("%ld^1 ", num);
    long i = 2;
    int exp = 0;
    while (i * i <= num) {
        if (num % i == 0) {
            exp = 0;
            while (num % i == 0) {
                num /= i;
                exp++;
            }
            if (exp > 1) {
                printf("%ld^%d ", i, exp);
            } else {
                printf("%ld ", i);
            }
        }
        i++;
    }
    if (num > 1) {
        printf("%ld\n", num);
    }
    return 0;
}
